#!/usr/bin/env python3
"""Render current editorial apparatus from inspected pages; makes no ink decisions."""
from pathlib import Path
import collections,csv,html,json
R=Path(__file__).resolve().parents[1]; S='SP115_CW_156-7'
pages=[json.loads(p.read_text()) for p in sorted((R/'review').glob('scan*_final.json'))]
def esc(s):return str(s).replace('|','&#124;').replace('\n','<br>')
def tex(s):return '<code>'+html.escape(str(s)).replace('|','&#124;').replace('\n','<br>')+'</code>'
notation=[
('Paired high quotation ticks',r"``...''",'All eight pages; guillemets are used only if drawn. Opening and closing marks are recorded separately where one is missing.'),
('Figure set, looped script capital',r'\mathscr F','Distinct from the plain figure variable F. Printer’s mathscr/mathcal mapping is uncertain at its first occurrence on scan004; later occurrences follow that choice.'),
('Multistrates and lieux',r'M; L','Ordinary M and L are the consistent editorial mappings of the hand. Calligraphic alternatives are registered at their first occurrences (003 and004), rather than repeatedly changing the alphabet.'),
('Inclusion / refinement',r'\leq; \ll','Two distinct source relations. At0 states inclusion implies refinement. No extra strictness is supplied.'),
('Strata / incidence',r'\widetilde F; X\triangleleft F','The source defines tilde F as the multistrates X≤F. The triangle points left; it is distinct from the pair of refinement chevrons.'),
('Compatibility',r'\mathrel{\tikz{...}}','Two opposed open chevrons cross to form a central diamond, reproduced by the same TikZ strokes. It is the source relation whose definition refers to a common upper bound.'),
('Set of strata versus decorated figure family',r'\widetilde F; \widetilde{\mathscr F}; \overline{\mathscr F}','The first is the strata of one figure; the second is the represented family. A clearly straight overbar on scan005 b′ is retained, even though the family context suggests a tilde.'),
('Large / small multiombre operators',r'\mathrm{Mulomb}; \mathrm{mulomb}; \mathrm{Omb}; \mathrm{omb}','No t is inserted into Mulomb or mulomb. Capitalization distinguishes the large construction on multistrates from the small construction on lieux (003–004).'),
('Empty figure / empty set',r'\varnothing_{\mathscr F}; \varnothing; \phi','Slashed-oval and long-stemmed phi forms are distinguished by visible strokes. On006 At_M2 the long-stemmed phi means l’ensemble vide. Retain any source subscript; no symbol is changed solely to standardize its mathematical meaning.'),
('Greek capital Phi',r'\Phi','Oval crossed by a central stem; capital in the family conditions on005. Small lowered Phi remains distinguished by placement and the whole formula.'),
('Order-specific infima',r'\mathrm{Inf}^{\leq}; \mathrm{Inf}^{\ll}','The relation is raised on Inf. The lower dot in F·G on004 is reproduced close to the baseline.'),
('Axiom labels and manuscript numbers','At 0; At 1–At 7; manuscript pages 1–8','At has no period. Revisions of a number are transcribed, not inferred from the sequence.'),
('Same / même abbreviations',r'\overline{\mathrm m}; =','Overlined m and the equals sign in en = temps remain abbreviations. Expansions are confined to the list below.'),
]
doubts=['# Notation table and remaining doubts','', '## Notation table','', '| Source form | Transcription | Scope and decision |','|---|---|---|']
for a,b,c in notation:doubts.append('| '+esc(a)+' | '+tex(b)+' | '+esc(c)+' |')
doubts += ['', 'The table records one editorial notation across the cote. It does not resolve a local letter, numeral, cancellation, or decoration when the ink remains ambiguous. First-occurrence font alternatives are not an assertion that different symbols are intended.', '', '## Remaining doubts', '', '| Scan | Place | Reading | Alternatives | Confidence | Evidence / limitation |','|---:|---|---|---|---|---|']
for d in pages:
 for q in d.get('doubts',[]):doubts.append('| '+' | '.join([f"{d['scan']:03d}",esc(q['place']),tex(q['reading']),tex(q.get('alternatives','')),q['confidence'],esc(q.get('reason',''))])+' |')
abbr=[('Cf; cf','compare / see'),('p.','page(s)'),('At','axiome'),('ens; ens.','ensemble'),('multistr.','multistrate'),('NB; NB.','nota bene'),('tjrs','toujours'),('néc.','nécessairement'),('déf; def; défn; defn; dfn; df', 'définition; scan006 retains dfn/df/defn/défn/déf alternatives, and scan008 retains dfn/defn/def alternatives. The abbreviated forms and accents remain source-specific and unexpanded in the transcription.'),('rel b.; rel\\textsuperscript{tion}', 'Unresolved abbreviated relation label on scan006; no certain expansion is assigned. Both candidates remain unexpanded in the transcription, followed by the written comma.'),('p. r.', 'Uncertain alternative to pour on scan006; possibly par rapport (à), as a tentative editorial expansion only. The transcription retains pour/p. r. without expansion.'),('t.f.; tf','type fini'),('i.e.','id est'),('sym','symétrique'),('extrinsèq.; intrinsèq.','extrinsèque / intrinsèque; the source choice remains doubtful'),('Cor; Cor.','corollaire'),('Contre-ex.','contre-exemple'),('tt','tous / tout, according to context'),('gén.','général'),('ex','exemple, where used in the marginal introduction'),('contre-exple','contre-exemple'),('Cor. Main','Uncertain corollary label at both occurrences on scan009: Cor. Main is the primary candidate, with Main retained without expansion; Corollaire is the alternative.'),('ses','perhaps si et seulement si in its logical role; the literal letters ses are retained and not corrected to ssi'),(r'\overline{\mathrm m}; =','même')]
doubts += ['', '## Abbreviations', '', 'Only forms actually present in the completed transcription are applicable; source punctuation is preserved in the page files. Proposed expansions below are editorial and never inserted into the French text.', '', '| Written form | Proposed expansion |','|---|---|']
# Later page-specific additions are appended explicitly as their readings are finalized.
present='\n'.join((R/'pages'/f"H156-01_156-7_scan{d['scan']:03d}.tex").read_text() for d in pages)
for a,b in abbr:doubts.append('| '+tex(a)+' | '+esc(b)+' |')
doubts += ['', '## Legibility and confidence', '', 'The main horizontal prose is generally readable at the supplied resolution. Compressed endings, small alphabet choices, overwritten numerals, and cancelled letters require more caution. Diagonal margins, especially the long note on003 and crowded formulae later in the sequence, carry a larger share of the remaining doubt. Enlargement and sharpening cannot recover strokes absent from the supplied pixels.', '', 'Both witnesses can omit source state or normalize a plausible word. Agreement between them was not treated as evidence. H often regularizes quotations, abbreviations, grammatical endings, and mathematical letters; C is generally more explicit about cancellation and uncertainty, but also has unsupported punctuation, a wrong deletion boundary, and some apparently confident wrong symbols. The page-level counts are counts of recorded places, not a statistical estimate of either model’s general accuracy.', '', 'Pale background marks and show-through are excluded. Watermarks are paper features, not manuscript text, and are never given doubt tokens here.']
(R/(S+'_doubts.md')).write_text('\n'.join(doubts)+'\n')
kind_order=['misread symbol or index','misread word','omission','drawing or diagram',r'readable ink left as \ill{}','insertion or placement','deletion state (struck given live or live given struck)','abbreviation expanded or spelling modernised','text not on the page','other']
cs=[c for d in pages for c in d['changes']]
feedback=['# Error-sheet feedback','', 'One place is assigned one primary category. A record may differ from both witnesses; the union column counts it once. Doubt dispositions that leave the same primary source reading are separately visible in the changes log and are not treated as demonstrated witness errors. “Other” includes source quotation shapes, underlining and manuscript labels; mere macro translations are excluded.', '', '| Error-sheet category | Differences from C | Differences from H | Distinct places in either |','|---|---:|---:|---:|']
for k in kind_order:
 vals=[sum(c['kind']==k and bool(c.get('against_C')) for c in cs),sum(c['kind']==k and bool(c.get('against_H')) for c in cs),sum(c['kind']==k and bool(c.get('against_C') or c.get('against_H')) for c in cs)]
 feedback.append('| '+esc(k)+' | '+' | '.join(map(str,vals))+' |')
feedback += ['', '## Recurrences and qualifications', '', '- Open C-like letters need local comparators. The clear C forms in004–005 are retained even though a G would make the formula coherent. Small c/G forms remain doubtful. This belongs to the sheet’s existing symbol/slip category, not a new rule that all Cs are Gs.', '- A revision can cross an internal letter group within a word. The heading on004 illustrates why the deletion boundary must be read independently of the likely completed word.', '- H’s editorial descriptions can identify a source correction but still omit its literal text or render its state incorrectly. Editorial notes themselves are excluded; the ink is transcribed.', '- Detached paired quotation ticks are often converted into guillemets, and underlining can be extended or omitted. These are source-state differences, unlike an equivalent emph/uline macro choice.', '- A map-like shaft may have transverse strokes at both ends without an arrowhead (005 Scholie). Both ends must be read independently.', '- No new general error category is established by this small eight-page sample. The recurrent problems fit the supplied categories; the examples above refine their application.']
(R/(S+'_sheet_feedback.md')).write_text('\n'.join(feedback)+'\n')
print(f'Rendered doubts and feedback for {len(pages)} finalized pages.')
